const withArt=(b:Base,image=engineImage):Base=>({...b,featureImage:image,featureOverlay:true});

function oilPage(j:Job):SpecRecord{
  const r=oilGuide(withArt({...j,category:"Fluid Capacities",metaDescription:`${j.model} oil-capacity chart with filter-included values, generation breaks, refill procedure, dipstick checks, FAQs, cautions, and manufacturer sources.`,identity:j.model,distinctions:[j.context,j.caution]}));
  r.intro=[`${j.answer} That published capacity is a service starting point, not permission to empty the last fraction of a bottle into the crankcase. Drain time, oil temperature, cooler volume, filter construction, vehicle angle, and residual oil all affect the amount required to reach the dipstick's full mark.`,`${j.context} This guide separates the generations in the table, keeps filter-included and filter-excluded figures distinct, and explains a repeatable refill check. ${j.caution}`,"Refill below the listed total first, start the engine long enough to fill the filter, inspect for leaks, shut it down, wait on level ground, and finish by dipstick. That process protects against both an underfilled engine and the aeration, leakage, or catalyst trouble that overfilling can cause."];
  r.sections.unshift({heading:`The generation break that matters for ${j.model}`,paragraphs:[`${j.context} Read the model-year and engine row together; a badge, displacement, or oil cap by itself may span more than one internal engine revision. The values below are drain-and-refill quantities with the filter unless the row says otherwise.`,`${j.caution} Use the oil grade and manufacturer approval from the same model-year manual as the capacity. Capacity, viscosity, and approval are three separate specifications.`]});
  if (researchedOilSlugs.has(j.slug)) r.reviewed = "2026-08-21";
  return r;
}
function sparkPage(j:Job):SpecRecord{
  const r=sparkGuide(withArt({...j,category:"Ignition Specs",metaDescription:`${j.model} spark-plug gap chart with approved-part guidance, measurement and installation steps, troubleshooting, FAQs, and manufacturer sources.`,identity:j.model,distinctions:[j.context,j.caution]}));
  r.intro=[`${j.answer} Gap is only one part of the plug specification: thread reach, seat, heat range, resistor, electrode construction, and approved part number must also match. A plug can measure perfectly and still be wrong for the cylinder head.`,`${j.context} Use the table to identify the application before touching an electrode. ${j.caution} Modern fine-wire plugs are easy to damage with an old coin-style gauge or by levering against the center electrode.`,"Work on a cool engine, clean the plug wells, label coils, inspect each new plug, and start every thread by hand. If an approved fine-wire plug arrives substantially outside the stated range, replacing it is safer than forcing it into shape."];
  r.sections.unshift({heading:`Choosing the correct ${j.model} row`,paragraphs:[`${j.context} Match model year, engine code, emissions label, and the approved plug number. Where the table shows a range, a clean wire gauge should pass with light, even drag without scraping the precious-metal tip.`,`${j.caution} Modified boost, non-stock cylinder pressure, or an aftermarket calibration may have builder instructions, but a smaller internet-recommended gap is not a repair for weak coils, damaged boots, or fueling problems.`]});
  return r;
}
function lugPage(j:Job,sedan=false):SpecRecord{
  const r=lugGuide(withArt({...j,category:"Torque Specs",metaDescription:`${j.title}. Factory-wheel chart, clean-thread rule, staged tightening pattern, recheck guidance, FAQs, cautions, and manufacturer sources.`,identity:j.model,distinctions:[j.context,j.caution]},sedan?sedanImage:wheelImage));
  r.intro=[`${j.answer} The number matters, but the installation is safe only when the wheel is seated flat, the nut or bolt seat matches the wheel, and the threads have the dry condition assumed by the manual. Torque is a proxy for clamp load, so oil, rust, damaged plating, or an impact tool changes the result.`,`${j.context} The chart separates meaningful generation or trim differences instead of presenting one unsupported universal value. ${j.caution}`,"Hand-start every fastener, snug in an opposite-side pattern, apply final torque with a calibrated wrench, repeat the complete pattern, and perform the manufacturer's post-service recheck. The interactive pattern and printable reference below make that sequence easy to audit."];
  r.sections.unshift({heading:`Identify the ${j.model} hardware before tightening`,paragraphs:[`${j.context} Factory wheel diameter alone does not select torque; stud or bolt size, seat geometry, and platform do. Read the table by generation and trim, then verify any non-original hardware against its own instructions.`,`${j.caution} Clean corrosion from the hub pad and wheel mounting face without lubricating the seats or threads. A torque wrench cannot make a mismatched or cocked wheel sit correctly.`]});
  return r;
}

const firing=firingGuide(withArt({
  slug:"audi/3-0-tfsi/firing-order",keyword:"audi 3.0 tfsi firing order diagram",make:"Audi",model:"3.0L TFSI V6",category:"Firing Order",title:"Audi 3.0 TFSI Firing Order Diagram and Cylinder Numbering",
  metaDescription:"Audi 3.0 TFSI firing order 1-4-3-6-2-5 with cylinder-bank numbering, interactive diagram, coil identification, diagnostics, FAQs, and source links.",
  answer:"The common Audi EA837 3.0 TFSI V6 firing order is 1-4-3-6-2-5. Bank 1 contains cylinders 1-2-3 and Bank 2 contains 4-5-6; confirm the engine code because ‘3.0 TFSI’ spans more than one technical generation.",
  detail:"The supercharged EA837 and later turbocharged EA839 are not interchangeable service layouts even where their basic combustion sequence is shared.",scope:"Covers common Audi 3.0 TFSI V6 applications; engine-code-specific Audi repair information controls bank orientation, connector identity, and repair procedure.",
  values:[{label:"Firing order",value:"1-4-3-6-2-5",note:"Common Audi 3.0 TFSI V6 sequence"},{label:"Bank 1",value:"Cylinders 1-2-3",note:"Bank containing cylinder 1"},{label:"Bank 2",value:"Cylinders 4-5-6",note:"Confirm installed-engine orientation"},{label:"Ignition",value:"Coil-on-plug",note:"PCM controlled; no distributor routing"}],sources:[S.audi],identity:"Audi 3.0 TFSI V6",distinctions:["Identify the EA837/EA839 engine code before using component-location instructions.","Cylinder number, coil connector, and firing-event position are different diagnostic references."]
}));
firing.sections.unshift({heading:"Why the engine code belongs beside the diagram",paragraphs:["Audi used the 3.0 TFSI marketing name for supercharged and turbocharged V6 families. The firing order alone therefore cannot select a plug, coil, injector, torque procedure, or bank-access method. Record the engine code and VIN before removing the intake or disconnecting a harness.","Read bank numbers as Audi defines them in the engine-specific service information. Vehicle left/right descriptions can become confusing when a diagram is viewed from the front rather than from the driver's seat."]});

const silverado43Firing=firingGuide(withArt({
  slug:"chevrolet/silverado-1500/4-3/firing-order",keyword:"chevy silverado 4.3 firing order",make:"Chevrolet",model:"Silverado 4.3L V6",category:"Firing Order",title:"Chevy Silverado 4.3 Firing Order and Cylinder Numbering",
  metaDescription:"Chevy Silverado 4.3 firing order 1-6-5-4-3-2 with cylinder numbering, distributor and coil-system distinctions, interactive diagram, FAQs, and sources.",
  answer:"The traditional Chevrolet 4.3L V6 firing order is 1-6-5-4-3-2. Cylinders 1-3-5 are on the driver/left bank and 2-4-6 on the passenger/right bank, front to rear.",
  detail:"Older 4.3L engines use a distributor, while later versions use distributorless or coil-based ignition. The mechanical order stays the same, but the routing task changes.",scope:"Covers common Chevrolet Silverado/Sierra 4.3L V6 engines using the production firing order; verify engine RPO and ignition generation before routing wires or diagnosing coils.",
  values:[{label:"Firing order",value:"1-6-5-4-3-2",note:"Production Chevrolet 4.3L V6"},{label:"Driver/left bank",value:"1-3-5",note:"Front to rear"},{label:"Passenger/right bank",value:"2-4-6",note:"Front to rear"},{label:"Ignition layout",value:"Varies by generation",note:"Distributor, distributorless, or coil-based"}],sources:[S.gm20,S.gm],identity:"Chevrolet 4.3L V6",distinctions:["The 4.3L V6 is not numbered like an inline engine; odd and even cylinders occupy opposite banks.","Identify distributor versus later ignition hardware before applying a cap-routing illustration."]
}));
silverado43Firing.sections.unshift({heading:"Separate the firing order from the ignition layout",paragraphs:["A 1990s Vortec distributor cap and a later Silverado coil system can share the same 1-6-5-4-3-2 combustion sequence while looking completely different above the engine. Use the order to identify the next power event, then use the engine-specific diagram to identify the cap post, coil tower, or connector that serves that cylinder.","On a distributor engine, establish cylinder 1 at compression top dead center and observe the rotor before calling any physical cap position number 1. Distributor installation position can move the practical No. 1 terminal without changing the firing order."]});

